<article class="product-card"><img class="product-image" src="<?= e(image_url($product['imagen'])) ?>" width="480" height="320" alt="<?= e($product['nombre']) ?>"><div class="product-body"><h3><?= e($product['nombre']) ?></h3><p><?= e($product['descripcion']) ?></p><div class="price-row"><strong><?= money(cents($product['precio'])) ?></strong><span class="badge <?= $product['stock'] < 10 ? 'warning' : '' ?>"><?= e($product['stock']) ?> disponibles</span></div>
<?php if ($role === 'comprador'): ?><form class="product-actions" method="post" action="/"><?= csrf_field() ?><input type="hidden" name="action" value="add"><input type="hidden" name="id" value="<?= e($product['id']) ?>"><div class="quantity"><button type="button" data-quantity-step="-1" aria-label="Reducir cantidad">−</button><input name="cantidad" type="number" min="1" max="<?= e(min(999, (int)$product['stock'])) ?>" value="1" required aria-label="Cantidad de <?= e($product['nombre']) ?>"><button type="button" data-quantity-step="1" aria-label="Aumentar cantidad">+</button></div><button <?= !$product['stock'] ? 'disabled' : '' ?>>Agregar</button></form>
<?php elseif (!$user): ?><a class="button secondary wide" href="/login.php">Inicia sesión para comprar</a><?php else: ?><p class="form-help">Las compras requieren una cuenta de comprador.</p><?php endif; ?></div></article>
